contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 trigger) public {
        require(trigger <= 1, "INVALID_TRIGGER");

        uint32 rBefore = c._RState_(); if (__ESBMC_reverted()) return;
        uint112 baseReserveBefore = c._BASE_RESERVE_(); if (__ESBMC_reverted()) return;
        uint112 quoteReserveBefore = c._QUOTE_RESERVE_(); if (__ESBMC_reverted()) return;
        uint112 baseTargetBefore = c._BASE_TARGET_(); if (__ESBMC_reverted()) return;
        uint112 quoteTargetBefore = c._QUOTE_TARGET_(); if (__ESBMC_reverted()) return;

        c.correctRState(); if (__ESBMC_reverted()) return;

        uint32 rAfter = c._RState_(); if (__ESBMC_reverted()) return;
        uint112 baseTargetAfter = c._BASE_TARGET_(); if (__ESBMC_reverted()) return;
        uint112 quoteTargetAfter = c._QUOTE_TARGET_(); if (__ESBMC_reverted()) return;

        bool caseBelowTriggered = (rBefore == 2) && (uint256(baseReserveBefore) < uint256(baseTargetBefore));
        bool caseAboveTriggered = (rBefore == 1) && (uint256(quoteReserveBefore) < uint256(quoteTargetBefore));

        assert(
            caseBelowTriggered
                ? (rAfter == 0 && baseTargetAfter == baseReserveBefore && quoteTargetAfter == quoteReserveBefore)
                : caseAboveTriggered
                    ? (rAfter == 0 && baseTargetAfter == baseReserveBefore && quoteTargetAfter == quoteReserveBefore)
                    : (rAfter == rBefore && baseTargetAfter == baseTargetBefore && quoteTargetAfter == quoteTargetBefore)
        );
    }
}

