        c = new GSPFunding();
    }

    function _run(uint256 trigger) internal {
        trigger = bound(trigger, 0, 1);
        uint32 rBefore;
        try c._RState_() returns (uint32 __r) { rBefore = __r; } catch { return; }
        uint112 baseReserveBefore;
        try c._BASE_RESERVE_() returns (uint112 __r) { baseReserveBefore = __r; } catch { return; }
        uint112 quoteReserveBefore;
        try c._QUOTE_RESERVE_() returns (uint112 __r) { quoteReserveBefore = __r; } catch { return; }
        uint112 baseTargetBefore;
        try c._BASE_TARGET_() returns (uint112 __r) { baseTargetBefore = __r; } catch { return; }
        uint112 quoteTargetBefore;
        try c._QUOTE_TARGET_() returns (uint112 __r) { quoteTargetBefore = __r; } catch { return; }
        try c.correctRState() {} catch { return; }
        uint32 rAfter;
        try c._RState_() returns (uint32 __r) { rAfter = __r; } catch { return; }
        uint112 baseTargetAfter;
        try c._BASE_TARGET_() returns (uint112 __r) { baseTargetAfter = __r; } catch { return; }
        uint112 quoteTargetAfter;
        try c._QUOTE_TARGET_() returns (uint112 __r) { quoteTargetAfter = __r; } catch { return; }
        bool caseBelowTriggered = (rBefore == 2) && (uint256(baseReserveBefore) < uint256(baseTargetBefore));
